 const answerAssistant=(q:string)=>{const l=q.toLowerCase();if(l.includes('last')||l.includes('history')||l.includes('last month')||l.includes('last week')){const rows=s.events.filter(e=>e.date<today()&&(e.title.toLowerCase().includes(l.includes('gym')?'gym':l.includes('meeting')?'meeting':'')||!l.includes('gym')&&!l.includes('meeting'))).sort((a,b)=>b.date.localeCompare(a.date));if(!rows.length)return 'ORDER has no matching event history recorded yet.';return `From your saved events: ${rows.slice(0,3).map(e=>`${e.title} on ${fmt(e.date)}${e.status==='completed'?' (completed)':e.status==='canceled'?' (canceled)':''}`).join('; ')}.`}if(l.includes('overdue'))return `${s.tasks.filter(t=>!t.done&&t.date<today()).length} open tasks are overdue.`;if(l.includes('forget'))return `${s.captures.length} thoughts are in your inbox. ${next?`Next up: ${next.title}.`:''}`;if(l.includes('goal'))return `${s.goals.length} goals are active. Highest priority: ${s.goals.slice().sort((a,b)=>b.priority-a.priority)[0]?.name||'none yet'}.`;if(l.includes('30 min'))return tasksToday.find(t=>!t.duration||t.duration<=30)?.title||'Your Today list is clear.';return next?`I’d start with “${next.title}.” ${nextMoveScore(next,s.goals).reason}`:'You have no open tasks on Today.'};
