function sanitizeAiSettings(action:any,type:'goal'|'event'){const result:any={type,title:String(action.title||'')};const numeric=type==='goal'?['priority','importance','impact','commitment','difficulty','confidence','alignment','health']:['priority','duration','importance','impact'];for(const key of numeric){const value=Number(action[key]);if(action[key]!==undefined&&action[key]!==null&&action[key]!==''&&Number.isFinite(value)){const min=key==='priority'&&type==='event'?1:key==='duration'?0:1,max=key==='priority'&&type==='event'?4:key==='duration'?1440:10;result[key]=Math.min(max,Math.max(min,Math.round(value)))}}if(type==='goal'){const categories=['Business','Health','Faith','Family','Financial','Personal Development','Home'];const category=String(action.category||'');result.category=categories.find(value=>value.toLowerCase()===category.toLowerCase())||categories.find(value=>category.toLowerCase().includes(value.toLowerCase()));if(!result.category)delete result.category;if(['daily','weekly','monthly','quarterly'].includes(action.reviewFrequency))result.reviewFrequency=action.reviewFrequency;if(Array.isArray(action.milestones))result.milestones=action.milestones.filter((value:any)=>typeof value==='string'&&value.trim()).slice(0,6)}else {if(typeof action.eventType==='string'&&action.eventType.trim())result.eventType=action.eventType.trim().slice(0,60);if(Array.isArray(action.reminders))result.reminders=[...new Set(action.reminders.map(Number).filter((n:number)=>[5,10,15,30,60,1440].includes(n)))].slice(0,3)}return result}
function describeAiProposal(action:any,s:State){if(action.type==='capture')return `Save note · ${action.text||action.title}`;if(action.type==='start_timer')return `Start stopwatch${action.categoryId?` · ${s.timeCategories.find(c=>c.id===action.categoryId)?.name||'selected category'}`:''}`;if(action.type==='stop_timer')return 'Stop focus timer';if(action.type==='update_settings')return `Update settings · ${Object.entries(action.updates||{}).map(([key,value])=>`${key} → ${Array.isArray(value)?value.join(', '):String(value)}`).join(' · ')}`;if(action.type==='create_calendar')return `Create calendar · ${action.title||action.name} · ${action.color||'default color'}`;if(action.type==='update_calendar')return `Update calendar · ${s.calendars.find(c=>c.id===action.calendarId)?.name||action.calendarId}: ${Object.entries(action.updates||{}).map(([key,value])=>`${key} → ${String(value)}`).join(' · ')}`;if(action.type==='update_task'||action.type==='complete_task'||action.type==='set_priority'||action.type==='reschedule_task'){const current=s.tasks.find(t=>t.id===action.taskId);const label=current?.title||action.taskId||'task';if(action.type==='update_task')return `Update task · ${label}: ${Object.entries(action.updates||{}).map(([key,value])=>`${key} → ${Array.isArray(value)?value.join(', '):String(value)}`).join(' · ')}`;return action.type==='complete_task'?`Complete task · ${label}`:action.type==='set_priority'?`Change priority · ${label} → P${action.priority}`:`Reschedule task · ${label} → ${action.date||'undated'}`}if(action.type==='update_goal'){const current=s.goals.find(g=>g.id===action.goalId);return `Update goal · ${current?.name||action.goalId}: ${Object.keys(action.updates||{}).join(', ')}`}if(action.type==='update_event'){const current=s.events.find(e=>e.id===action.eventId);return `Update event · ${current?.title||action.eventId}: ${Object.keys(action.updates||{}).join(', ')}`}if(action.type==='set_goal_progress'||action.type==='add_milestone'){const current=s.goals.find(g=>g.id===action.goalId);return action.type==='set_goal_progress'?`Set progress · ${current?.name||action.goalId} → ${action.progress}%`:`Add milestone · ${current?.name||action.goalId}: ${action.title}`}if(action.type==='set_event_status'){const current=s.events.find(e=>e.id===action.eventId);return `Change event status · ${current?.title||action.eventId} → ${action.status}`}return action.type==='event'?`Create event · ${action.title||''} · ${fmt(action.date||today())}`:`${action.type||'Change'} · ${action.title||''}${action.date?` · ${fmt(action.date)}`:''}`}
 async function askOrder(message:string,s:State,contextOverride?:any){const endpoint=import.meta.env.DEV?'/api/assistant':'https://order-one-bay.vercel.app/api/assistant';const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(contextOverride?{message,context:contextOverride}:{message,context:{date:today(),settings:aiPreferenceContext(s.settings,s),activeTimer:s.activeTimer||null,entries:s.entries.map(e=>({project:e.project,start:e.start,end:e.end,goal:e.goal,categoryId:e.categoryId,color:e.color,notes:e.notes})),timeCategories:s.timeCategories, tasks:s.tasks.map(t=>({id:t.id,title:t.title,date:t.date,done:t.done,completedAt:t.completedAt,priorityLevel:t.priorityLevel,goal:t.goal,eventId:t.eventId,postponed:t.postponed,duration:t.duration,dependencies:t.dependencies,importance:t.importance,impact:t.impact,urgency:t.urgency,effort:t.effort,confidence:t.confidence})),goals:s.goals.map(g=>({id:g.id,name:g.name,category:g.category,description:g.description,target:g.target,priority:g.priority,progress:g.progress,milestones:g.milestones})),events:s.events.map(e=>({id:e.id,title:e.title,date:e.date,start:e.start,end:e.end,status:e.status,completedAt:e.completedAt,description:e.description,notes:e.notes,location:e.location,goal:e.goal,priority:e.priority,importance:e.importance,impact:e.impact,duration:e.duration,eventType:e.eventType,allDay:e.allDay,timezone:e.timezone,reminders:e.reminders,recurrence:e.recurrence,taskIds:e.taskIds})),history:s.events.flatMap(e=>Array.from({length:60},(_,i)=>shift(today(),-i-1)).filter(d=>d>=e.date&&eventOccurs(e,d)).map(d=>{const occurrence=eventOn(e,d)!;return{id:occurrence.id,title:occurrence.title,date:d,status:occurrence.status||'scheduled',completedAt:occurrence.completedAt}})).filter((item:any)=>item.status!=='scheduled').slice(0,60),captures:s.captures.map(c=>({text:c.text,date:c.date})),calendars:s.calendars.map(c=>({id:c.id,name:c.name,color:c.color,visible:c.visible}))}})});const raw=await response.text();let result:any;try{result=JSON.parse(raw)}catch{throw new Error('ORDER AI returned an invalid response. Check the Vercel API deployment and try again.')}if(!response.ok)throw new Error(result.error||'AI request failed');try{return JSON.parse(result.text)}catch{return{reply:result.text,actions:[]}}}
function entrySeconds(entry:Entry){return Math.max(0,Math.floor((new Date(entry.end).getTime()-new Date(entry.start).getTime())/1000))}
function RescheduleCoach({task,close,resolve,disable}:{task:Task;close:()=>void;resolve:(reason:RescheduleReason|undefined,action:RescheduleAction)=>void;disable:()=>void}){const [reason,setReason]=useState<RescheduleReason|undefined>();const options:[RescheduleReason,string][]=[['ran_out_of_time','I ran out of time'],['more_important','Something more important came up'],['took_longer','This took longer than expected'],['waiting','I’m waiting on something'],['hard_to_start','I’m not sure how to start'],['low_energy','I don’t have the energy right now'],['not_important','This isn’t important now'],['other','Something else']];return <div className="backdrop reschedule-backdrop" onMouseDown={close}><section className="sheet reschedule-sheet" onMouseDown={e=>e.stopPropagation()}><SheetHead title={reason?'A small adjustment':'Plans change'} sub={task.title} close={close}/>{!reason?<><p className="reschedule-prompt">What got in the way this time? This is optional and just helps ORDER suggest a better fit.</p><div className="reschedule-options">{options.map(([key,label])=><button key={key} onClick={()=>setReason(key)}>{label}<ArrowRight size={14}/></button>)}</div><footer className="reschedule-foot"><button className="quiet" onClick={()=>resolve(undefined,'tomorrow')}>Skip and reschedule</button><button className="quiet" onClick={disable}>Turn off check-ins</button></footer></>:<><p className="reschedule-prompt">Here are a few ways to adjust “{task.title}”. You can still edit the task before saving a new time.</p><div className="reschedule-options">{rescheduleSuggestions(reason).map((option,index)=><button key={`${option.action}-${index}`} onClick={()=>resolve(reason,option.action)}>{option.label}<ArrowRight size={14}/></button>)}</div><button className="quiet" onClick={()=>setReason(undefined)}>Back</button></>}</section></div>}

function HomeOverview({s,tab,setTab,defaultTab,setDefaultTab,order,setOrder,open,toggle}:{s:State;tab:string;setTab:(x:string)=>void;defaultTab:string;setDefaultTab:(x:string)=>void;order:string[];setOrder:(f:(x:string[])=>string[])=>void;open:(k:string,x?:any)=>void;toggle:(id:string)=>void}){const todayKey=dayKey(),days=[todayKey,shift(todayKey,1),shift(todayKey,2)],dayNames=['Today','Tomorrow',fmt(days[2],{weekday:'long'})];const tasks=s.tasks.filter(t=>!t.done&&[t.dueDate||t.date,t.scheduledDate].some(d=>Boolean(d&&days.includes(d))));const events=s.events.filter(e=>e.status!=='canceled'&&(s.calendars.find(c=>c.id===e.calendar)?.visible??true)).flatMap(e=>days.map(d=>eventOn(e,d)).filter((x):x is EventItem=>Boolean(x)));const goals=s.goals.filter(g=>!['completed','archived'].includes(g.status||'active'));const goalItems=goals.flatMap(g=>[...(g.target&&days.includes(g.target)?[{kind:'goal' as const,date:g.target,time:'',title:g.name,detail:'Goal target',item:g}]:[]),...(g.milestoneDetails||[]).filter(m=>m.targetDate&&days.includes(m.targetDate)&&m.status!=='completed').map(m=>({kind:'goal' as const,date:m.targetDate!,time:'',title:g.name,detail:`Milestone · ${m.title}`,item:g}))]);const items=[...goalItems,...tasks.map(task=>({kind:'task' as const,date:task.scheduledDate&&days.includes(task.scheduledDate)?task.scheduledDate:(task.dueDate||task.date),time:task.time,title:task.title,item:task})),...events.map(event=>({kind:'event' as const,date:event.date,time:event.start,title:event.title,item:event}))].sort((a,b)=>a.date.localeCompare(b.date)||a.time.localeCompare(b.time));const active=order.includes(tab)?tab:'All';const move=(index:number,delta:number)=>setOrder(current=>{const next=[...current],target=index+delta;if(target<0||target>=next.length)return current;[next[index],next[target]]=[next[target],next[index]];return next});const row=(x:any)=><div className="overview-row" key={`${x.kind}:${x.item.id}:${x.date}`}><button className="overview-open" onClick={()=>open(x.kind==='goal'?'goal':x.kind,x.item)}><i className={`overview-kind ${x.kind}`}>{x.kind==='task'?'T':x.kind==='event'?'E':'G'}</i><span><b>{x.title}</b><small>{fmt(x.date,{weekday:'short',month:'short',day:'numeric'})}{x.time?` · ${x.time}`:''}{x.detail?` · ${x.detail}`:''}{x.kind==='task'&&x.item.goal?` · ${x.item.goal}`:''}{x.kind==='event'&&x.item.location?` · ${x.item.location}`:''}</small></span></button>{x.kind==='task'&&<button className="overview-check" aria-label={`Complete ${x.title}`} onClick={()=>toggle(x.item.id)}><Check size={15}/></button>}</div>;return <section className="home-overview"><header className="overview-head"><div><span className="eyebrow">THE NEXT THREE DAYS</span><h2>All</h2></div><label>Open Home with<select aria-label="Default Home overview tab" value={defaultTab} onChange={e=>setDefaultTab(e.target.value)}>{['All','Tasks','Goals','Events'].map(x=><option key={x}>{x}</option>)}</select></label></header><div className="overview-tabs" role="tablist" aria-label="Upcoming overview">{order.map((name,index)=><div className="overview-tab-wrap" key={name}><button role="tab" aria-selected={active===name} className={active===name?'selected':''} onClick={()=>setTab(name)}>{name}</button><div className="overview-reorder"><button aria-label={`Move ${name} earlier`} disabled={index===0} onClick={()=>move(index,-1)}>↑</button><button aria-label={`Move ${name} later`} disabled={index===order.length-1} onClick={()=>move(index,1)}>↓</button></div></div>)}</div>{active==='Goals'?<div className="overview-list">{goals.length?goals.slice(0,8).map(g=><button className="overview-goal" key={g.id} onClick={()=>open('goal',g)}><span><b>{g.name}</b><small>{g.status||'active'}{g.target?` · Target ${fmt(g.target,{month:'short',day:'numeric'})}`:''}</small><i><em style={{width:`${Math.max(0,Math.min(100,g.progress||0))}%`}}/></i></span><strong>{g.progress||0}%</strong></button>):<p className="overview-empty">No active goals right now.</p>}</div>:<div className="overview-list">{(active==='Tasks'?items.filter(x=>x.kind==='task'):active==='Events'?items.filter(x=>x.kind==='event'):items).length?days.map((date,index)=>{const list=(active==='Tasks'?items.filter(x=>x.kind==='task'):active==='Events'?items.filter(x=>x.kind==='event'):items).filter(x=>x.date===date);return list.length?<section className="overview-day" key={date}><h3>{dayNames[index]}</h3>{list.map(row)}</section>:null}):<p className="overview-empty">Nothing needs your attention in the next three days.</p>}</div>}</section>}

function TimerPage({s,seconds,start,stop,updateEntry,addCategory}:{s:State;seconds:number;start:(id?:string)=>void;stop:()=>void;updateEntry:(e:Entry)=>void;addCategory:(name:string,color:string)=>string}){const [categoryId,setCategoryId]=useState(s.timeCategories[0]?.id||'focus'),[name,setName]=useState(''),[color,setColor]=useState(()=>timerPalette.find(candidate=>!s.timeCategories.some(c=>c.color.toLowerCase()===candidate.toLowerCase()))||'#A98965'),[categoryError,setCategoryError]=useState(''),[noteDrafts,setNoteDrafts]=useState<Record<string,string>>({});const active=s.activeTimer,category=s.timeCategories.find(c=>c.id===(active?.categoryId||categoryId))||s.timeCategories[0],activeTask=s.tasks.find(t=>t.id===active?.taskId);const entries=s.entries.slice().sort((a,b)=>b.start.localeCompare(a.start)),total=s.entries.reduce((sum,e)=>sum+entrySeconds(e),0);const byCategory=s.timeCategories.map(c=>({category:c,seconds:s.entries.filter(e=>(e.categoryId||'')===c.id||(!e.categoryId&&e.project===c.name)).reduce((sum,e)=>sum+entrySeconds(e),0)}));const createCategory=()=>{setCategoryError('');const id=addCategory(name,color);if(id){setCategoryId(id);setName('');setColor(timerPalette.find(candidate=>!s.timeCategories.some(c=>c.color.toLowerCase()===candidate.toLowerCase())&&candidate.toLowerCase()!==color.toLowerCase())||'#7D9B93')}else setCategoryError('Use a new category name and an unused color.')};return <div className="timer-page"><div className="page-title"><div><small className="eyebrow">TIME CLOCK · LOG</small><h1>Time Clock</h1><p>Clock in to record work. Clock out to save your time.</p></div></div><section className="stopwatch-card"><div className="stopwatch-top"><span className="time-category-dot" style={{background:category?.color||'#9BAA88'}}/><b>{category?.name||'Focus'}</b><small>{active?(activeTask?`Tracking task · ${activeTask.title}`:'Recording time'):'Ready when you are'}</small></div>{active?<div className="stopwatch-readout">{formatStopwatch(seconds)}</div>:<div className="stopwatch-readout">00:00:00</div>}{!active&&<label className="timer-category-select">Category<select value={categoryId} onChange={e=>setCategoryId(e.target.value)}>{s.timeCategories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label>}<button type="button" className={active?'stopwatch-stop':'stopwatch-start'} onClick={()=>active?stop():start(categoryId)}>{active?'Clock Out':'Clock In'}</button></section><div className="clock-summary-grid"><article><small>Today</small><b>{formatStopwatch(s.entries.filter(e=>e.start.slice(0,10)===today()).reduce((n,e)=>n+entrySeconds(e),0)+(active?seconds:0))}</b></article><article><small>This week</small><b>{formatStopwatch(s.entries.filter(e=>{const d=e.start.slice(0,10),now=today(),startOfWeek=shift(now,-((new Date(now+'T12:00:00').getDay()+6)%7));return d>=startOfWeek&&d<=now}).reduce((n,e)=>n+entrySeconds(e),0)+(active?seconds:0))}</b></article><article><small>Recent sessions</small><b>{entries.length}</b></article></div><details className="timer-more"><summary>Time insights, categories, and session log</summary><section className="timer-categories"><div className="section-head"><h2>Time by category</h2><b>{Math.floor(total/3600)}h {Math.floor(total%3600/60)}m total</b></div><div className="category-summary">{byCategory.map(({category:c,seconds:secs})=><div key={c.id}><i style={{background:c.color}}/><span>{c.name}</span><b>{Math.floor(secs/3600)}h {Math.floor(secs%3600/60)}m</b></div>)}</div><div className="new-category"><input value={name} onChange={e=>setName(e.target.value)} placeholder="Add a category…"/><input aria-label="Category color" type="color" value={color} onChange={e=>setColor(e.target.value)}/><button type="button" className="quiet" disabled={!name.trim()} onClick={createCategory}>Add category</button>{categoryError&&<small className="category-error">{categoryError}</small>}</div></section><section className="timer-log"><div className="section-head"><h2>Session log <span>{entries.length}</span></h2></div>{entries.length?entries.map(entry=>{const item=s.timeCategories.find(c=>c.id===(entry.categoryId||'')),entryCategory=item?.name||entry.project||'Focus',entryColor=item?.color||entry.color||'#9BAA88';return <article className="timer-entry" key={entry.id} style={{borderLeftColor:entryColor}}><div className="timer-entry-meta"><b>{entryCategory}{entry.taskId&&s.tasks.find(t=>t.id===entry.taskId)?` · ${s.tasks.find(t=>t.id===entry.taskId)?.title}`:''}</b><span>{new Date(entry.start).toLocaleDateString()} · {new Date(entry.start).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}</span><strong>{Math.floor(entrySeconds(entry)/3600)}h {Math.floor(entrySeconds(entry)%3600/60)}m</strong></div><select aria-label="Session category" value={entry.categoryId||s.timeCategories.find(c=>c.name===entry.project)?.id||s.timeCategories[0]?.id||''} onChange={e=>{const c=s.timeCategories.find(x=>x.id===e.target.value);if(c)updateEntry({...entry,categoryId:c.id,project:c.name,color:c.color})}}>{s.timeCategories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select><input aria-label="Session note" value={noteDrafts[entry.id]??entry.notes??''} onChange={e=>setNoteDrafts(x=>({...x,[entry.id]:e.target.value}))} onBlur={e=>updateEntry({...entry,notes:e.target.value})} placeholder="Add or edit a note…"/></article>}):<div className="empty">Your stopped sessions will appear here. You can add categories and notes whenever you like.</div>}</section></details></div>}
function formatStopwatch(seconds:number){const value=Math.max(0,Math.floor(seconds));return `${String(Math.floor(value/3600)).padStart(2,'0')}:${String(Math.floor(value%3600/60)).padStart(2,'0')}:${String(value%60).padStart(2,'0')}`}
function QuickCapture({busy,onSave,onClose}:{busy:boolean;onSave:(text:string)=>void;onClose:()=>void}){const {confirm}=useDialogs();const [text,setText]=useState('');const input=useRef<HTMLTextAreaElement>(null),submitted=useRef(false);const submit=()=>{if(!text.trim()||busy||submitted.current)return;submitted.current=true;onSave(text)};const close=async()=>{if(text.trim()&&!await confirm({title:'Discard capture?',message:'Your unsaved capture will be discarded.',confirmLabel:'Discard',destructive:true}))return;onClose()};useEffect(()=>{input.current?.focus();const key=(e:KeyboardEvent)=>{if(e.key==='Escape'){e.preventDefault();close()}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();submit()}};window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key)},[text,busy]);return <div className="backdrop capture-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><section className="sheet capture-sheet"><div className="sheet-head"><div><h2>Capture</h2><p>Get it out of your head. Sort it later.</p></div><button className="icon" aria-label="Close capture" onClick={close}><X size={17}/></button></div><textarea ref={input} className="quick-capture-text" value={text} onChange={e=>setText(e.target.value)} placeholder="A task, idea, note, question… anything" rows={4}/><div className="capture-footer"><small>Saved to your Inbox · Ctrl/⌘ + Enter to capture</small><button className="primary" disabled={!text.trim()||busy} onClick={submit}><Send size={14}/>{busy?'Saving…':'Capture'}</button></div></section></div>}
